package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Take the sheet's figures before the change, so the change's audit can record how they moved. */
public class TakeRollup {
    public void take(@PathVariable("sheetId") String sheetId, Rollups rollups, Out<Rollup> before) {
        before.set(rollups.take(sheetId.trim()));
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.rate.RateInput;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Record, after the change's own lines, how the sheet's figures moved over it. */
public class AuditRateRollup {
    public void audit(@PathVariable("sheetId") String sheetId, @Val RateInput request, @Val Rollup before,
            Rollups rollups) {
        rollups.record(sheetId.trim(), request.user(), before);
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the sheet id has never been loaded. */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository)
            throws SheetNotFoundException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.exists(id)) {
            throw new SheetNotFoundException(id);
        }
    }
}
