          }}
        />
      </label>{' '}
      <button type="submit" data-testid="import-rates-submit" disabled={importRates.isPending}>
        Import rates
      </button>
      {result !== null && (
        <>
          {' '}Set <span data-testid="import-rates-set">{result.set}</span>
        </>
      )}
      {error && (
        <p data-testid="import-rates-error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

